sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amplitude;
uniform float wavelength;
uniform float speed;
uniform float angle;
uniform float phase;
uniform float mode;
uniform float shear;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float a = radians(angle);
    float2 dir = float2(cos(a), sin(a));
    float2 nrm = float2(-dir.y, dir.x);
    float arg = dot(coord, dir) / max(wavelength, 1.0) * 6.2831853 + time * speed * 6.2831853 + radians(phase);
    float w = sin(arg);
    if (mode > 0.5 && mode < 1.5) w = abs(fract(arg / 6.2831853) * 2.0 - 1.0) * 2.0 - 1.0;
    else if (mode > 1.5) w = (vnoise(float2(arg, 3.7)) - 0.5) * 2.0;
    float2 q = coord + nrm * w * amplitude;
    q.x += (q.y - size.y * 0.5) * shear;
    return fin(c, texT(q), opacity);
}
